// `out` holds the CCW intersection, or fewer than 3 vertices when degenerate.
//
// Each clip edge evaluates orient() once per subject vertex, carrying the
// previous vertex's side into the next iteration.  The textbook walk
// recomputes that side, doubling the inner-loop predicates.
inline void clip_convex_ccw(std::vector<std::array<double, 2>>& subject,
                            const std::vector<std::array<double, 2>>& clip_poly,
                            std::vector<std::array<double, 2>>& out,
                            std::vector<std::array<double, 2>>& in) {
    const int clip_n = static_cast<int>(clip_poly.size());
    // subject is not read after this; swap avoids copying the polygon.
    out.swap(subject);
    in.clear();
    for (int e = 0; e < clip_n && out.size() >= 3; ++e) {
        const int e1 = (e + 1 == clip_n) ? 0 : e + 1;
        const double ax = clip_poly[e][0],  ay = clip_poly[e][1];
        const double bx = clip_poly[e1][0], by = clip_poly[e1][1];
        in.swap(out);
        out.clear();
        const int sz = static_cast<int>(in.size());
        out.reserve(sz + 2);
        int prev = sz - 1;
        double prv_side = orient(ax, ay, bx, by, in[prev][0], in[prev][1]);
        for (int i = 0; i < sz; ++i) {
            const auto& cur = in[i];
            const auto& prv = in[prev];
